#define QR_HW_RUNTIME_BASEADDR      ((UINTPTR)XPAR_QR_RUNTIME_EXACT_0_BASEADDR)
#define QR_HW_RESULT_DMA_BASEADDR   ((UINTPTR)XPAR_AXI_DMA_0_BASEADDR)
#define QR_HW_IMAGE_DMA_BASEADDR    ((UINTPTR)XPAR_AXI_DMA_IMAGE_BASEADDR)
