#define QR_HW_IMAGE_WIDTH           640U
#define QR_HW_IMAGE_HEIGHT          480U
#define QR_HW_IMAGE_STRIDE          640U
#define QR_HW_IMAGE_BYTES           307200U
#define QR_HW_QRP1_MAX_WORDS        85U
#define QR_HW_QRP1_MAX_BYTES        340U

#define QR_HW_I2C_SCLK_HZ           50000U

/*
 * qr_perf PL: 62.5 MHz / 2 = 31.25 MHz XCLK. CLKRC bit7=0 keeps
 * PCLK <= XCLK/2; receiver has at least four PL cycles per PCLK period.
 * CLKRC=1 is the verified default. Override to 0 for the faster experimental
 * profile without rebuilding PL (more QR misses in the current indoor scene).
 */
#ifndef QR_CAMERA_CLKRC
#define QR_CAMERA_CLKRC 1U
#endif
#ifndef QR_CAMERA_SOURCE_SYNC
#define QR_CAMERA_SOURCE_SYNC 0
#endif
#if !QR_CAMERA_SOURCE_SYNC && (QR_CAMERA_CLKRC != 0 && QR_CAMERA_CLKRC != 1)
#error "Double-clock sensor profiles require stage3 source-synchronous CAM3 hardware."
#endif
#if QR_CAMERA_SOURCE_SYNC && (QR_CAMERA_CLKRC != 0 && QR_CAMERA_CLKRC != 1 && QR_CAMERA_CLKRC != 128 && QR_CAMERA_CLKRC != 129)
#error "Unsupported stage3 clock profile."
#endif
#define QR_HW_OV7670_CLKRC_BRINGUP   QR_CAMERA_CLKRC

/* Current preprocessing convention: black/foreground is represented as 1. */
#ifndef QR_HW_FRONTEND_FE_MODE
#define QR_HW_FRONTEND_FE_MODE       0x0000003DU
#endif
#define QR_HW_FRONTEND_FB_INVERT     1U
#define QR_HW_FRONTEND_PROGRAM_THRESH 0U
#define QR_HW_FRONTEND_THRESH         0x00000000U
#define QR_HW_FRONTEND_PROGRAM_GEOM   0U
#define QR_HW_FRONTEND_GEOM           0x00000000U

#endif
